INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2d0df7c5-6c73-4984-90bb-4df5c957925a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'avatar-group', 'AvatarGroup', 'Data Display', NULL, 'mdi-account-group', 'components.catalog.avatar_group.description', 'Stacked group of Avatar components with overflow counter, expand-on-hover and expand-on-click behaviours.', NULL, NULL, 'origam-avatar-group', NULL, 'packages/ds/src/components/Avatar/OrigamAvatarGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-avatar--design', '/docs/components/Avatar/OrigamAvatarGroup.html', 'avatar', '{"a11y": {"notes": [{"noteKey": "components.avatar_group.a11y.role_note", "noteFallback": "The root element has role=\"group\" to semantically group related avatars for screen readers."}, {"noteKey": "components.avatar_group.a11y.collapse_note", "noteFallback": "When expandOnClick=true, clicking outside the group (v-click-outside) collapses it automatically."}, {"noteKey": "components.avatar_group.a11y.reduced_motion_note", "noteFallback": "Transition on the overlap margin respects prefers-reduced-motion via the transition-property var."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.avatar_group.a11y.key_tab", "actionFallback": "Moves focus through each interactive avatar within the group."}, {"key": "Enter / Space", "actionKey": "components.avatar_group.a11y.key_activate", "actionFallback": "Activates expand-on-click behaviour when expandOnClick=true."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "0px", "tokenPath": "--origam-avatar-group---density", "descriptionKey":