ot</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"37\" y1=\"28\" x2=\"70\" y2=\"12\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"74\" y=\"14\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-col</text>\n", "code": "<div class=\"origam-col origam-col--6 origam-col--md-4\">\n  <slot name=\"default\" />\n</div>", "legend": [{"cls": ".origam-col", "num": 1, "descriptionKey": "components.col.anatomy.root", "descriptionFallback": "Root element (defaults to <code>&lt;div&gt;</code>). Responsive modifiers such as <code>origam-col--6</code>, <code>origam-col--md-4</code> and <code>origam-col--offset-2</code> are generated from props."}], "classes": [{"cls": "origam-col", "descriptionKey": "components.col.anatomy.root", "descriptionFallback": "Base flex column class."}, {"cls": "origam-col--{n}", "descriptionKey": "components.col.anatomy.size", "descriptionFallback": "Column span modifier (1–12 or auto)."}, {"cls": "origam-col--{bp}-{n}", "descriptionKey": "components.col.anatomy.breakpoint_size", "descriptionFallback": "Breakpoint-specific span modifier, e.g. origam-col--md-6."}, {"cls": "origam-col--offset-{n}", "descriptionKey": "components.col.anatomy.offset", "descriptionFallback": "Left-margin offset in columns."}, {"cls": "origam-col--align-{value}", "descriptionKey": "components.col.anatomy.align", "descriptionFallback": "align-self override (start, end, center, baseline, stretch)."}, {"cls": "origam-col--order-{value}", "descriptionKey": "components.col.anatomy.order", "descriptionFallback": "CSS order override (0–12, first, last)."}], "svgDesc": "Schematic of Col with root and content slot.", "svgTitle": "Anatomy of OrigamCol", "rootClass": "origam-col", "figcaption": "Anatomy of <code>&lt;origam-col&gt;</code> — 1 root element with a default slot. BEM size/offset/order modifiers are generated dynamically from props.", "svgViewBox": "0 0 500 120"}, "cssVars": [{"name": "--origam-col---width", "defaultValue": "100%", "descriptionKey": "components.col.css_vars.width", "descriptionFallback": "Default column width before breakpoint modifiers are applied."}, {"name": "--origam-col---flex-basis", "defaultValue": "0", "descriptionKey": "components.col.css_vars.flex_basis", "descriptionFallback": "Flex basis. Overridden per span modifier to calc(100% / (12 / n))."}, {"name": "--origam-col---flex-grow", "defaultValue": "1", "descriptionKey": "components.col.css_vars.flex_grow", "descriptionFallback": "flex-grow value. Set to 0 for auto columns."}, {"name": "--origam-col---padding-inline-start", "defaultValue": "12px", "descriptionKey": "components.col.css_vars.padding_inline_start", "descriptionFallback": "Horizontal gutter — start side. Matches the Row gutter half-width."}, {"name": "--origam-col---padding-inline-end", "defaultValue": "12px", "descriptionKey": "components.col.css_vars.padding_inline_end", "descriptionFallback": "Horizontal gutter — end side."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.col.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.col.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.col.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.col.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.col.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.col.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.col.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.col.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
