INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0e5db7d5-d0ec-4e7a-bfca-d6ce564dc55d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'expansion-panel', 'ExpansionPanel', 'Layout & Structure', NULL, 'mdi-chevron-down-box-outline', 'components.catalog.expansion_panel.description', 'Collapsible panel with animated header and content reveal. Supports accordion, popout and inset layout modes; optional loader, ripple and density controls.', NULL, NULL, 'origam-expansion-panel', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanel.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.expansion_panel.a11y.aria_expanded", "noteFallback": "The header button carries aria-expanded=\"true|false\" reflecting the current panel state. Screen readers announce the expanded/collapsed status."}, {"noteKey": "components.expansion_panel.a11y.aria_controls", "noteFallback": "The header button carries aria-controls pointing to the content region ID. The content region carries aria-labelledby pointing to the header ID."}, {"noteKey": "components.expansion_panel.a11y.disabled", "noteFallback": "Disabled panels use tabindex=\"-1\" on the header and add aria-disabled via the disabled HTML attribute."}, {"noteKey": "components.expansion_panel.a11y.reduced_motion", "noteFallback": "The expand/collapse animation respects prefers-reduced-motion: the transition-duration is overridden to 0ms."}], "roles": ["button", "region"], "keyboard": [{"key": "Enter / Space", "actio