-origam-overlay-scrim---opacity", "descriptionKey": "components.overlay_scrim.tokens.opacity", "descriptionFallback": "Default opacity (0.32)."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-overlay-scrim---transition-duration", "descriptionKey": "components.overlay_scrim.tokens.transition_duration", "descriptionFallback": "Duration of the opacity fade animation."}, {"type": "other", "value": "fixed", "tokenPath": "--origam-overlay-scrim---position", "descriptionKey": "components.overlay_scrim.tokens.position", "descriptionFallback": "Positioning strategy — always fixed to cover the viewport."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"644\" height=\"160\" rx=\"4\" fill=\"rgba(0,0,0,0.32)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"108\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" opacity=\"0.8\">position: fixed · inset: 0 · opacity: 0.32</text>\n  <circle cx=\"36\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"28\" x2=\"80\" y2=\"14\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"13\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-scrim</text>\n", "code": "<!-- OrigamTransition wraps for enter/leave animation -->\n<origam-transition :transition=\"transition\">\n  <div\n    v-if=\"active\"\n    class=\"origam-scrim\"\n    aria-hidden=\"true\"\n    @click=\"emit(''click'', $event)\"\n    @mouseenter=\"emit(''mouseenter'', $event)\"\n    @mouseleave=\"emit(''mouseleave'', $event)\"\n  />\n</origam-transition>", "legend": [{"cls": ".origam-scrim", "num": 1, "descriptionKey": "components.overlay_scrim.anatomy.root", "descriptionFallback": "Root element. <code>position: fixed; inset: 0; opacity: 0.32</code>. Conditionally rendered via <code>v-if=\"active\"</code> wrapped in <code>&lt;origam-transition&gt;</code>. Has <code>aria-hidden=\"true\"</code>."}], "classes": [{"cls": "origam-scrim", "descriptionKey": "components.overlay_scrim.anatomy.root", "descriptionFallback": "Root element. Fixed, full-viewport, semi-transparent backdrop. background-color driven by scrim prop or --origam-overlay-scrim---background-color."}], "svgDesc": "Schematic of the OverlayScrim component — a single fixed-position overlay element.", "svgTitle": "Anatomy of OrigamOverlayScrim", "rootClass": "origam-scrim", "figcaption": "Anatomy of <code>&lt;origam-overlay-scrim&gt;</code> — a single <code>div.origam-scrim</code> positioned <code>fixed</code> with <code>inset: 0</code>. Wrapped in an <code>&lt;origam-transition&gt;</code> (OrigamFade by default).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-overlay-scrim---background-color", "defaultValue": "{color.overlay.scrim}", "descriptionKey": "components.overlay_scrim.css_vars.background_color", "descriptionFallback": "Scrim background color. Aliased to color.overlay.scrim. Overridden inline when scrim prop is a color string."}, {"name": "--origam-overlay-scrim---opacity", "defaultValue": "0.32", "descriptionKey": "components.overlay_scrim.css_vars.opacity", "descriptionFallback": "Opacity of the backdrop. 0.32 matches Material Design spec."}, {"name": "--origam-overlay-scrim---pointer-events", "defaultValue": "auto", "descriptionKey": "components.overlay_scrim.css_vars.pointer_events", "descriptionFallback": "Pointer event handling. Set to none to make the scrim click-through."}, {"name": "--origam-overlay-scrim---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.overlay_scrim.css_vars.transition_duration", "descriptionFallback": "Duration of the opacity transition on enter/leave."}, {"name": "--origam-overlay-scrim---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.overlay_scrim.css_vars.transition_timing_function", "descriptionFallback": "Easing function for the opacity transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.overlay_scrim.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.overlay_scrim.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.overlay_scrim.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.overlay_scrim.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.overlay_scrim.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.overlay_scrim.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "active", "labelKey": "components.overlay_scrim.playground.active", "defaultValue": true, "labelFallback": "Active"}, {"kind": "select", "prop": "scrim", "options": [{"label": "(default)", "value": ""}, {"label": "rgba(0,0,0,0.5)", "value": "rgba(0,0,0,0.5)"}, {"label": "rgba(0,0,128,0.4)", "value": "rgba(0,0,128,0.4)"}, {"label": "rgba(124,58,237,0.3)", "value": "rgba(124,58,237,0.3)"}], "labelKey": "components.overlay_scrim.playground.scrim", "defaultValue": "", "labelFallback": "Scrim color"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
