INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7bcba998-0cfd-41d5-91fd-e89059e5e1a0', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'switch', 'Switch', 'Form & Input', NULL, 'mdi-toggle-switch-outline', 'components.catalog.switch.description', 'Toggle switch input that wraps a hidden checkbox for binary on/off state, with optional inset style, loading states and track slot customization.', NULL, NULL, 'origam-switch', NULL, 'packages/ds/src/components/Switch/OrigamSwitch.vue', 'origam', NULL, NULL, '/stories/?story=components-switch--design', '/docs/components/Switch/OrigamSwitch.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.switch.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.switch.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.switch.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}, {"kind": "switch", "prop": "flat", "labelKey": "components.switch.playground.flat", "defaultValue": false, "labelFallback": "Flat"}, {"kind": "text", "prop": "label", "labelKey": "components.switch.playground.label", "defaultValue": "", "labelFallback": "Label"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.switch.playground.indeterminate", "defau