INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fee1df63-47c9-491e-bd1f-d5be8fe351e7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'switch-track', 'SwitchTrack', 'Form & Input', NULL, 'mdi-toggle-switch-outline', 'components.catalog.switch_track.description', 'The rounded rail behind the Switch thumb. Owns its visual surface (background, inset variant, error state) and exposes slots for content shown on each side of the rail.', NULL, NULL, 'origam-switch-track', NULL, 'packages/ds/src/components/Switch/OrigamSwitchTrack.vue', 'origam', NULL, NULL, '/stories/?story=components-switch--design', '/docs/components/Switch/OrigamSwitch.html', 'switch', '{"a11y": {"notes": [{"noteKey": "components.switch_track.a11y.presentational_note", "noteFallback": "SwitchTrack is a purely visual sub-component. All ARIA semantics (role=\"switch\", aria-checked, aria-label) live on the hidden <input> or the SelectionControl root inside OrigamSwitch — not on the track itself."}, {"noteKey": "components.switch_track.a11y.forced_colors_note", "noteFallback": "Under forced-colors: active a 1px border is rendered and colour transitions are disabled so the track remains distinguishable from the background. The ON state paints the track highlight colour."}, {"noteKey": "components.switch_track.a11y.reduced_motion_note", "noteFallback": "The background-color transition is removed under prefers-reduced-motion: reduce."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "44px", "tokenPath": "--origam-switch__track---width", "descriptionKey": "components.switch_track.tokens.width", "descriptionFallback": "Width of the standard track."}, {"type": "dimension", "value": "24px", "tokenPath": "--origam-switch__track---height", "descriptionKey": "components.switch_track.tokens.height", "descriptionFallback": "Height of the standard track."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-switch__track---border-radius", "descriptionKey": "components.switch_track.tokens.border_radius", "descriptionFallback": "Pill border-radius of the track."}, {"type": "color", "value": "color-mix(in srgb, var(--origam-color__text---primary) 60%, var(--origam-color__surface---default))", "tokenPath": "--origam-switch__track---background-color", "descriptionKey": "components.switch_track.tokens.background_color", "descriptionFallback": "Track background in OFF state."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-switch__track---background-color-checked", "descriptionKey": "components.switch_track.tokens.background_color_checked", "descriptionFallback": "Track background in ON state."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-switch__track---background-color-error", "descriptionKey": "components.switch_track.tokens.background_color_error", "descriptionFallback": "Track background in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"190\" y=\"40\" width=\"320\" height=\"100\" rx=\"50\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"88\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-switch-track--dirty</text>\n  <rect x=\"202\" y=\"52\" width=\"80\" height=\"76\" rx=\"38\" fill=\"var(--origam-color__surface---overlay, rgba(255,255,255,0.15))\" stroke=\"none\"/>\n  <text x=\"242\" y=\"92\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">true</text>\n  <rect x=\"418\" y=\"52\" width=\"80\" height=\"76\" rx=\"38\" fill=\"var(--origam-color__surface---overlay, rgba(0,0,0,0.08))\" stroke=\"none\"/>\n  <text x=\"458\" y=\"92\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">false</text>\n  <circle cx=\"462\" cy=\"90\" r=\"42\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"none\"/>\n  <circle cx=\"198\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"198\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"210\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"210\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"426\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"426\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"470\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"470\" y=\"64\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-switch-track origam-switch-track--dirty\">\n  <!-- left content: visible when ON -->\n  <div class=\"origam-switch-track__true\">\n    <slot name=\"track.true\" v-bind=\"{ model: modelValue, isValid }\" />\n  </div>\n  <!-- right content: visible when OFF -->\n  <div class=\"origam-switch-track__false\">\n    <slot name=\"track.false\" v-bind=\"{ model: modelValue, isValid }\" />\n  </div>\n  <!-- free overlay layer -->\n  <slot name=\"overlay\" v-bind=\"{ model: modelValue, isValid }\" />\n</div>", "legend": [{"cls": ".origam-switch-track", "num": 1, "descriptionKey": "components.switch_track.anatomy.root", "descriptionFallback": "Root element. Pill-shaped rail with <code>border-radius: 9999px</code>. Carries state modifiers: <code>--dirty</code> (ON), <code>--disabled</code>, <code>--readonly</code>, <code>--error</code>, <code>--inset</code>."}, {"cls": ".origam-switch-track__true", "num": 2, "descriptionKey": "components.switch_track.anatomy.true", "descriptionFallback": "Left half — hosts the <code>#track.true</code> slot. Visible (opacity: 1) when <code>modelValue</code> is true, hidden (opacity: 0) when false. Uses <code>margin-inline-end: auto</code> to push to the left."}, {"cls": ".origam-switch-track__false", "num": 3, "descriptionKey": "components.switch_track.anatomy.false", "descriptionFallback": "Right half — hosts the <code>#track.false</code> slot. Visible when <code>modelValue</code> is false, hidden when true. Uses <code>margin-inline-start: auto</code> to push to the right."}, {"cls": "(overlay slot)", "num": 4, "descriptionKey": "components.switch_track.anatomy.overlay", "descriptionFallback": "<code>#overlay</code> slot host rendered after the half-labels. Positioned freely inside the track (absolute positioning is the consumer''s responsibility)."}], "classes": [{"cls": "origam-switch-track", "descriptionKey": "components.switch_track.anatomy.root", "descriptionFallback": "Root pill-shaped rail element with state modifiers."}, {"cls": "origam-switch-track__true", "descriptionKey": "components.switch_track.anatomy.true", "descriptionFallback": "Left (ON-side) content wrapper. Opacity-toggled by --dirty."}, {"cls": "origam-switch-track__false", "descriptionKey": "components.switch_track.anatomy.false", "descriptionFallback": "Right (OFF-side) content wrapper. Opacity-toggled by --dirty."}], "svgDesc": "Schematic of the SwitchTrack component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamSwitchTrack", "rootClass": "origam-switch-track", "figcaption": "Anatomy of <code>&lt;origam-switch-track&gt;</code> — 4 internal parts. The pill-shaped rail paints the background; the <code>__true</code> / <code>__false</code> halves reveal or hide on each side; the <code>overlay</code> slot sits on top.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-switch__track---background-color", "defaultValue": "rgb(163, 163, 163)", "descriptionKey": "components.switch_track.css_vars.background_color", "descriptionFallback": "Rail background colour in OFF state. Overridden by bgColor prop when set."}, {"name": "--origam-switch__track---border-radius", "defaultValue": "9999px", "descriptionKey": "components.switch_track.css_vars.border_radius", "descriptionFallback": "Corner radius of the track rail (pill shape)."}, {"name": "--origam-switch__track---height", "defaultValue": "14px", "descriptionKey": "components.switch_track.css_vars.height", "descriptionFallback": "Height of the standard (non-inset) track."}, {"name": "--origam-switch__track---width", "defaultValue": "36px", "descriptionKey": "components.switch_track.css_vars.width", "descriptionFallback": "Minimum width of the standard (non-inset) track."}, {"name": "--origam-switch__track--inset---height", "defaultValue": "32px", "descriptionKey": "components.switch_track.css_vars.inset_height", "descriptionFallback": "Height of the track in inset variant."}, {"name": "--origam-switch__track--inset---width", "defaultValue": "52px", "descriptionKey": "components.switch_track.css_vars.inset_width", "descriptionFallback": "Minimum width of the track in inset variant."}, {"name": "--origam-switch__track---background-color-disabled", "defaultValue": "rgb(163, 163, 163)", "descriptionKey": "components.switch_track.css_vars.background_color_disabled", "descriptionFallback": "Rail background in disabled ON state."}, {"name": "--origam-switch---opacity-disabled", "defaultValue": "0.32", "descriptionKey": "components.switch_track.css_vars.opacity_disabled", "descriptionFallback": "Opacity applied to the entire track in disabled state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.switch_track.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.switch_track.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed track styles."}, {"name": "id", "type": "string", "descriptionKey": "components.switch_track.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.switch_track.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.switch_track.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.switch_track.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.switch_track.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.switch_track.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.switch_track.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.switch_track.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}, {"kind": "switch", "prop": "modelValue", "labelKey": "components.switch_track.playground.model_value", "defaultValue": false, "labelFallback": "Value"}, {"kind": "switch", "prop": "error", "labelKey": "components.switch_track.playground.error", "defaultValue": false, "labelFallback": "Error"}, {"kind": "switch", "prop": "inset", "labelKey": "components.switch_track.playground.inset", "defaultValue": false, "labelFallback": "Inset"}]}, "previewVariants": [{"label": "off", "props": {"modelValue": false}}, {"label": "on", "props": {"modelValue": true}}, {"label": "inset off", "props": {"inset": true, "modelValue": false}}, {"label": "inset on", "props": {"inset": true, "modelValue": true}}, {"label": "disabled", "props": {"disabled": true, "modelValue": false}}, {"label": "error", "props": {"error": true, "modelValue": false}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3daa1e8c-408b-4fc6-a6b7-932b6398bd5c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'system-bar', 'SystemBar', 'Layout & Structure', NULL, 'mdi-dock-top', 'components.catalog.system_bar.description', 'Thin bar anchored to the top of an app layout — typically used to display status icons, time or network info in a narrow stripe.', NULL, NULL, 'origam-system-bar', NULL, 'packages/ds/src/components/SystemBar/OrigamSystemBar.vue', 'origam', NULL, NULL, '/stories/?story=components-system-bar--design', '/docs/components/SystemBar/OrigamSystemBar.html', NULL, '{"playground": {"controls": [{"kind": "switch", "prop": "window", "labelKey": "components.system_bar.playground.window", "defaultValue": false, "labelFallback": "Window"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('aeec2b10-fd5a-42af-92d1-8ddc86b1d4d9', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'component', 'tab', 'Tab', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab.description', 'Single registered tab inside an OrigamTabs tablist — renders the label text and optional leading/trailing icons.', NULL, NULL, 'origam-tab', NULL, 'packages/ds/src/components/Tabs/OrigamTab.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab.a11y.aria_note", "noteFallback": "OrigamTab wires role=\"tab\", aria-selected, aria-controls (pointing to the matching panel id) and aria-disabled automatically — no manual ARIA needed on the consumer side."}, {"noteKey": "components.tab.a11y.disabled_note", "noteFallback": "When disabled=true the tab gets aria-disabled=\"true\" and tabindex=-1; click events are swallowed via handleClick guard."}, {"noteKey": "components.tab.a11y.focus_note", "noteFallback": "Focus-visible outline is applied via :focus-visible pseudo-class (2px solid currentColor, outline-offset: -2px). Never shown on mouse click."}, {"noteKey": "components.tab.a11y.reduced_motion_note", "noteFallback": "The indicator transform transition should be disabled under prefers-reduced-motion: reduce via the consuming theme."}], "roles": ["tab"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.tab.a11y.key_activate", "actionFallback": "Activates the tab (selects it in the group)."}, {"key": "ArrowLeft / ArrowRight", "actionKey": "components.tab.a11y.key_arrows", "actionFallback": "Moves focus to the previous / next tab in the tablist (roving tabindex managed by OrigamTabs)."}, {"key": "Tab", "actionKey": "components.tab.a11y.key_tab", "actionFallback": "Moves focus outside the tablist to the next focusable element (tabpanel)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-tabs__item---color", "descriptionKey": "components.tab.tokens.item_color", "descriptionFallback": "Resting label color."}, {"type": "dimension", "value": "var(--origam-space---12)", "tokenPath": "--origam-tabs__item---height", "descriptionKey": "components.tab.tokens.item_height", "descriptionFallback": "Minimum tab height."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-tabs__item---font-weight", "descriptionKey": "components.tab.tokens.item_font_weight", "descriptionFallback": "Resting label font weight."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__item---transition-duration", "descriptionKey": "components.tab.tokens.item_transition_duration", "descriptionFallback": "Transition duration for color and background changes."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-tabs__indicator---color", "descriptionKey": "components.tab.tokens.indicator_color", "descriptionFallback": "Underline indicator color for variant=\"underline\"."}, {"type": "dimension", "value": "var(--origam-border__width---2)", "tokenPath": "--origam-tabs__indicator---height", "descriptionKey": "components.tab.tokens.indicator_height", "descriptionFallback": "Thickness of the underline indicator."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"52\" width=\"520\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"100\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <rect x=\"152\" y=\"66\" width=\"256\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"280\" y=\"95\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <rect x=\"420\" y=\"66\" width=\"80\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"460\" y=\"95\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append icon</text>\n  <rect x=\"40\" y=\"128\" width=\"520\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"50\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"88\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"74\" r=\"9\" fill=\"var(--origam-co