onnector", "descriptionFallback": "Connector line. Hidden on last item when truncateLine is active."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline_item.anatomy.content", "descriptionFallback": "Content wrapper. flex: 1."}, {"cls": "origam-timeline-item__header", "descriptionKey": "components.timeline_item.anatomy.header", "descriptionFallback": "Header row with title and subtitle."}, {"cls": "origam-timeline-item__title", "descriptionKey": "components.timeline_item.anatomy.title", "descriptionFallback": "Title text element."}, {"cls": "origam-timeline-item__subtitle", "descriptionKey": "components.timeline_item.anatomy.subtitle", "descriptionFallback": "Subtitle text element."}, {"cls": "origam-timeline-item__body", "descriptionKey": "components.timeline_item.anatomy.body", "descriptionFallback": "Body text area. Only rendered when description or body slot is present."}], "svgDesc": "Schematic of the TimelineItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimelineItem", "rootClass": "origam-timeline-item", "figcaption": "Anatomy of <code>&lt;origam-timeline-item&gt;</code> — 7 internal parts. The track holds the dot and connector; the content area holds the header (title + subtitle) and the body.", "svgViewBox": "0 0 640 260"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "14px", "descriptionKey": "components.timeline_item.css_vars.gap", "descriptionFallback": "Gap between the track and the content area."}, {"name": "--origam-timeline---track-width", "defaultValue": "24px", "descriptionKey": "components.timeline_item.css_vars.track_width", "descriptionFallback": "Fixed width of the track column (holds dot + connector)."}, {"name": "--origam-timeline---dot-size", "defaultValue": "12px", "descriptionKey": "components.timeline_item.css_vars.dot_size", "descriptionFallback": "Diameter of the timeline dot circle."}, {"name": "--origam-timeline-item---dot-bg", "defaultValue": "var(--origam-timeline---dot-bg)", "descriptionKey": "components.timeline_item.css_vars.dot_bg", "descriptionFallback": "Per-item dot background color. Set via intent-resolved CSS custom property on the dot element style."}, {"name": "--origam-timeline-item---dot-color", "defaultValue": "var(--origam-timeline---dot-color)", "descriptionKey": "components.timeline_item.css_vars.dot_color", "descriptionFallback": "Per-item dot foreground (icon) color. Set via intent-resolved CSS custom property."}, {"name": "--origam-timeline---dot-border-width", "defaultValue": "2px", "descriptionKey": "components.timeline_item.css_vars.dot_border_width", "descriptionFallback": "Border width of the dot circle (separates dot from background)."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline_item.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "1px", "descriptionKey": "components.timeline_item.css_vars.connector_thickness", "descriptionFallback": "Thickness of the connector line."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "0.875rem", "descriptionKey": "components.timeline_item.css_vars.title_font_size", "descriptionFallback": "Font size of the item title text."}, {"name": "--origam-timeline---title-font-weight", "defaultValue": "600", "descriptionKey": "components.timeline_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the item title text."}, {"name": "--origam-timeline---subtitle-font-size", "defaultValue": "0.75rem", "descriptionKey": "components.timeline_item.css_vars.subtitle_font_size", "descriptionFallback": "Font size of the subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline_item.exposed.filter_props", "descriptionFallback"