INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3085772e-770b-4a13-894e-e457bc1c59e9', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-installed-themes', 'useInstalledThemes', NULL, 'Theme', 'mdi-palette-swatch-outline', '', 'Returns the static list of brand themes installed via createOrigam({ themes }). Each entry contains the brand name and the concrete modes it was installed for. Use this to build a theme switcher that stays in sync with whatever the app registered, without hard-coding available brand names.', NULL, 'function useInstalledThemes(): TInstalledThemes', NULL, NULL, 'packages/ds/src/composables/Commons/installed-themes.composable.ts', NULL, NULL, 'The returned list is a static snapshot taken at createOrigam() call time — it does not change at runtime. Pair with useTheme() to read and switch the currently active brand and mode.', NULL, NULL, NULL, '{"consumedInterfaces": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
