INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9d8f5da9-befd-455e-b41c-10495f14892a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-padding', 'usePadding', NULL, 'Commons', 'mdi-arrow-collapse-all', '', 'Resolves the `padding` shorthand prop into utility classes for spacing-scale steps (0–12) or inline padding declarations for custom values. Mirror of useMargin for the padding axis.', NULL, 'function usePadding(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cd3705ca-1dd7-4f5e-8b9a-f1f62d7a3b60', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-paginated-items', 'usePaginatedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function usePaginatedItems(options: { items: Ref<readonly (T | IDataTableGroup<T>)[]> startIndex: Ref<number> stopIndex: Ref<number> itemsPerPage: Ref<number> }): { paginatedItems: ComputedRef<readonly (T | IDataTableGroup<T>)[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/paginatedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('346bea55-1901-433c-b880-9b8a491bb555', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-pagination', 'usePagination', NULL, 'DataTable', 'mdi-book-open-page-variant-outline', '', 'Suite of three pagination helpers for OrigamDataTable: createPagination initialises page and itemsPerPage refs from props; providePagination computes derived state (startIndex, stopIndex, pageCount) and provides it to children; usePagination injects the provided pagination context. A fourth helper usePaginatedItems slices the items array for the current page.', NULL, '// Initialise pagination refs from props
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b0f33be9-aa72-4bb1-97aa-019d4f37635a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-parallax', 'useParallaxRuntime', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Headless parallax engine used by OrigamParallax. Maintains a registry of layers, tracks scroll progress via IntersectionObserver, and drives per-frame transforms via requestAnimationFrame. Branches automatically to a CSS scroll-driven animation path (Chrome 115+) when the easing is linear and the browser supports animation-timeline: scroll(). Respects prefers-reduced-motion at OS level.', NULL, 'function useParallaxRuntime(options: IUseParallaxRuntimeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8683ccd8-77c6-4175-9931-aa7edfd1cc13', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6fc93454-5dc3-4082-8bec-10a6623ab8f6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-passed-props', 'usePassedProps', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function usePassedProps(_props: T, instanceLabel?: string = ''usePassedProps''): (key: Extract<keyof T, string> | string) => boolean', NULL, NULL, 'packages/ds/src/composables/Commons/passedProps.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8041cd8b-0f5e-476b-a9c9-888bc901b68d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-password-strength', 'computeStrength', NULL, 'PasswordField', 'mdi-shield-lock-outline', '', 'Pure function (no Vue reactivity needed) that scores a password string on a 0-4 scale based on length, digit presence, case diversity, and special characters. Returns a numeric score and a semantic level (weak / fair / good / strong). Used internally by OrigamPasswordField to drive the strength bar colour and label. No third-party dependencies.', NULL, 'function computeStrength(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2f3bab3d-995a-497e-8114-9fe0f13eba26', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-position', 'usePosition', NULL, 'Commons', 'mdi-map-marker-outline', '', 'Derives CSS positioning classes and inline style declarations from IPositionProps. Emits a BEM modifier class for the position variant (absolute, fixed, sticky, relative, static) and inline top/bottom/left/right properties for any offset props that are set.', NULL, 'function usePosition(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('67844327-05fb-462b-a3d8-baa01ec7d724', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-progress', 'useProgress', NULL, 'Progress', 'mdi-progress-clock', '', 'Computes all state needed to render a progress bar or circular progress indicator: a normalised 0-100 value from modelValue and max, thickness as a number, a visibility flag tied to IntersectionObserver, and BEM class/style arrays that handle indeterminate, striped, active, and absolute modes. Used by OrigamProgressLinear and OrigamProgressCircular.', NULL, 'function useProgress(props: IProgressTypeProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c668c6be-e97e-4228-824a-2b4e405a6dcf', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7716d898-c311-4b77-8d29-b9b1f4adfba7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f1f3d7cd-9c6b-4fe5-9e64-01b115022ffc', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f00abfcc-6ab7-4f20-8368-c42f3bdfdeaa', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f4994251-6f66-4389-b24d-9231ae075732', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-rounded', 'useRounded', NULL, 'Commons', 'mdi-rounded-corner', '', 'Resolves the `rounded` prop to border-radius classes and inline styles. Supports the modern utility taxonomy (xs/sm/md/lg/xl/none/full), the legacy named variants (x-small/small/default/medium/large/x-large/shaped), numbers and free-form CSS values.', NULL, 'function useRounded(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('136885dc-c873-4751-b0df-850f62fbee9e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-route', 'useRoute', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRoute(): Ref<RouteLocationNormalizedLoaded | undefined>', NULL, NULL, 'packages/ds/src/composables/Commons/route.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('824916df-354d-4fa1-ae5d-46b58e665d6e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-router', 'useRouter', NULL, 'Commons', 'mdi-routes', '', 'Thin wrappers around Vue Router that expose the current route and router instance from the Vue component instance rather than via direct vue-router import. Also provides useLink (a link-resolution helper used by all clickable Origam components) and useBackButton (navigation guard for hardware/browser back button interception).', NULL, '// Returns the active route as a reactive ref
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('42266598-3dbc-46d5-bbab-b098b97e08f1', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-rtl', 'useRtl', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRtl(name?: string = getCurrentInstanceName()): { isRtl: Ref<boolean, boolean>; rtlClasses: ComputedRef<string>; }', NULL, NULL, 'packages/ds/src/composables/Commons/rtl.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('aa343494-8ad4-49d0-a06c-7f9d0abc7fe3', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-scope-id', 'useScopeId', NULL, 'Commons', 'mdi-identifier', '', 'Reads the Vue SFC scope ID from the current component instance and returns it as an attribute object. Used to ensure that teleported or dynamically-created DOM nodes receive the same scoped-CSS attribute as their parent component, so that scoped style rules continue to match across teleport boundaries.', NULL, 'function useScopeId(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('680cee6e-2f43-4145-b87f-e5ac3aff070c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-scroll', 'useScroll', NULL, 'Commons', 'mdi-gesture-swipe-vertical', '', 'Tracks scroll position and direction on a configurable target element (or window). Returns reactive flags for scroll direction, activity state, threshold crossing, and a scroll ratio useful for progressive UI transitions. Also exposes useScrollStrategies (apply named scroll behaviours like block, close, or reposition to floating overlays) and useScrolling (keyboard + scroll helpers for virtualised list + search-field combos).', NULL, 'function useScroll(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('849ea1f0-d244-428b-a259-ca1d5113a31e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-scrolling', 'useScrolling', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useScrolling(listRef: Ref<TOrigamList | undefined>, textFieldRef: Ref<TOrigamTextField | undefined>): { onListScroll: () => void; onListKeydown: (e: KeyboardEvent) => Promise<void>; }', NULL, NULL, 'packages/ds/src/composables/Commons/scrolling.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('156819e9-501b-400c-93dc-4d242a97cfb7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-select', 'useSelection', NULL, 'DataTable', 'mdi-checkbox-multiple-marked-outline', '', 'Inject accessor for the row-selection context provided by provideSelection inside OrigamDataTable. Returns the reactive selected Set and the select / toggleSelect / selectAll helpers plus status flags (someSelected, allSelected, showSelectAll). Used by checkbox columns and the header select-all control.', NULL, 'function useSelection(): IDataTableProvideSelection', NULL, NULL, 'packages/ds/src/composables/DataTable/select.composable.ts', NULL, NULL, 'useSelection throws when called outside a DataTable context (no inject match for ORIGAM_DATA_TABLE_SELECT_KEY). It must be used inside a component tree where provideSelection() was called by the parent table.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDataTableProvideSelection", "IDataTableSelectableItem", "IDataTableSelectProps"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0b508918-908d-4706-8c8f-026326e03c85', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-select-link', 'useSelectLink', NULL, 'Commons', 'mdi-link-variant', '', 'Bridges a router link and a group selection: when the link becomes active (current route matches), it automatically selects its group item. Used internally by navigation components (NavList, BottomNav, Tabs) so that a hard navigation or a programmatic router push keeps the selected state in sync without a manual v-model update.', NULL, 'function useSelectLink(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-sheet-swipe', 'useSheetSwipe', NULL, 'Sheet', 'mdi-gesture-swipe-up', '', 'Encapsulates bottom-sheet swipe gesture logic using Pointer Events (covers both mouse and touch). Tracks pointerdown → pointermove → pointerup on a dedicated handle element, resolves the target snap point on release via velocity (fast flick = step one snap) or absolute distance (slow drag = nearest snap), and exposes reactive drag state for 1:1 finger tracking during the gesture.', NULL, 'function useSheetSwipe(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fa138282-8148-421b-b52c-06b95bb3f76b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-size', 'useSize', NULL, 'Commons', 'mdi-magnify-plus-outline', '', 'Resolves the `size` prop to component-local modifier classes and optional width/height inline styles. Named presets (x-small/small/default/large/x-large) emit BEM modifier classes; custom values emit pixel dimensions.', NULL, 'function useSize(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e5f547f6-f6c9-4259-b2f9-26999014a3a6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-slider-field', 'useSteps', NULL, 'SliderField', 'mdi-tune-variant', '', 'Pure-function stepping math for OrigamSliderField. Computes reactive min / max / step / decimals values from the component props and exposes a roundValue helper that snaps any raw number to the nearest valid step (clamped to [min, max]). After the migration to a native <input type="range">, this is the only remaining logic layer for the slider — the browser now owns drag tracking.', NULL, 'function useSteps(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e5a5cd4c-4c01-47ec-9fa8-0ff8afa7a23c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-snackbar', 'useCountdown', NULL, 'Snackbar', 'mdi-timer-sand', '', 'Internal countdown timer used by OrigamSnackbar to drive the auto-dismiss progress indicator. Counts down from a given millisecond value using setInterval, ticking at the CSS transition duration of the host element so the progress bar remains visually synchronised. Exposes clear / reset / start controls and a reactive time ref.', NULL, 'function useCountdown(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('12f3b6c0-4a66-4667-a805-5d7576627748', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-snackbar-group', 'useSnackbarGroup', NULL, 'Snackbar', 'mdi-bell-outline', '', 'Module-level singleton store for a named snackbar stack. Push notifications via notify(), dismiss them by id or all at once. Each call sharing the same id option reads and writes the same reactive items list — the composable and the matching <OrigamSnackbarGroup id="…"> component share live state with no event bus required.', NULL, 'function useSnackbarGroup(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('54c36eb8-6fd2-4c64-9d73-9934bbb4bdaf', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-snackbar-group-internal', 'useSnackbarGroupInternal', 'Snackbar', 'Snackbar', NULL, NULL, NULL, NULL, 'function useSnackbarGroupInternal(id?: MaybeRefOrGetter<string> = SNACKBAR_GROUP_DEFAULT_ID): { rawItems: ComputedRef<ISnackbarGroupItem[]>; itemCount: ComputedRef<number>; registerDefaultDuration: (duration: number) => void; }', NULL, NULL, 'packages/ds/src/composables/Snackbar/snackbarGroupInternal.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1e777adc-0802-4b45-a983-ab39337452e4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'const', 'blockquote-langs', 'BLOCKQUOTE_LANGS', 'Typography', NULL, NULL, 'consts.catalog.blockquote_langs.description', 'Closed list of valid lang values for OrigamBlockquote. Controls which decorative quote glyphs are rendered. ''auto'' detects the page language at runtime.', 'export const BLOCKQUOTE_LANGS: ReadonlyArray<TBlockquoteLang> = Object.values(BLOCKQUOTE_LANG)', NULL, NULL, 'Object.values(BLOCKQUOTE_LANG)', 'packages/ds/src/consts/Blockquote/blockquote.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e8d101c6-a277-4a07-bdba-b4bb7a6b2d47', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-sort', 'useSort', NULL, 'DataTable', 'mdi-sort', '', 'Inject accessor for the sort context provided by provideSort inside OrigamDataTable. Returns the reactive sortBy array and the toggleSort / isSorted helpers. Used by header cells to read and update the active sort columns. The companion useSortedItems applies the sort order to a reactive item list.', NULL, 'function useSort(): IDataTableProvideSort
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('462bb447-c7e2-4aa1-a44c-a7e76fa1377f', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-sorted-items', 'useSortedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function useSortedItems(props: { customKeySort: TDataTableCompareFunction | undefined }, items: Ref<T[]>, sortBy: Ref<Array<IDataTableSortItem>>, options?: { transform?: (item: T) => Record<string, unknown> sortFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> sortRawFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> }): { sortedItems: ComputedRef<T[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/sortedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e278aac2-42f1-44f7-80ec-e8b74e8eb36c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-ssr-boot', 'useSsrBoot', NULL, 'Commons', 'mdi-server', '', 'Defers CSS transitions until after the first browser paint to prevent flash-of-transition on SSR hydration. Returns an isBooted flag (false during SSR and the first rAF frame, then true) and a ssrBootStyles computed that injects `transition: none !important` while booting, suppressing unwanted entry animations during hydration.', NULL, 'function useSsrBoot(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('430fa765-3eb6-4658-9b5b-e887ca2bc655', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-stack', 'useStack', NULL, 'Commons', 'mdi-layers-outline', '', 'Manages z-index stacking order for overlay components (Dialog, Menu, Tooltip, Drawer, …). Registers the component in the global GLOBAL_STACK array when it becomes active and auto-computes a z-index 10 units above the current topmost overlay. Exposes globalTop (is this the topmost overlay worldwide?) and localTop (does this overlay have no active child overlays?) for pointer-event and close-on-outside-click decisions.', NULL, 'function useStack(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fed4f028-1356-4f5e-8838-47893f6b494a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-state-effect', 'useStateEffect', NULL, 'Commons', 'mdi-palette-swatch-variant', '', 'Unified composable that consolidates eight visual axes (color, bgColor, border, rounded, elevation, padding, margin, gap) into a single state-aware layer. Reads the hover / active state and their override objects (IHoverState / IActiveState) and emits per-axis classes + styles for each axis. Replaces the prior chain of useColorEffect + useBorder + useRounded + useElevation + usePadding + useMargin that every visual component had to repeat.', NULL, 'function useStateEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('97ff2211-82e6-4a4c-ace6-ec9141253409', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-state-flag', 'useStateFlag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStateFlag(props: object, options: IStateFlagOptions<S>): IStateFlagReturn', NULL, NULL, 'packages/ds/src/composables/Commons/stateFlag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d82e371b-80f0-4369-b7bc-40e7359a6db4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-status', 'useStatus', NULL, 'Commons', 'mdi-alert-circle-outline', '', 'Resolves semantic status props (success, info, warning, error) into icon slots, status classes, and a forced intent color. The status intent overrides any color / bgColor the consumer passed — a status colour is non-negotiable by design. Also manages icon routing across prepend / append / replace slots based on statusIconPosition.', NULL, 'function useStatus(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('eae26b2c-93c3-4c00-b060-56fb9f41edd0', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-sticky', 'useSticky', NULL, 'Commons', 'mdi-pin-outline', '', 'Implements the "sticky-while-scrolling" pattern for taller-than-viewport navigation drawers. Tracks scroll direction and element bounding rect to decide whether the sidebar is stuck at the top, stuck at the bottom, or free-floating mid-page. Returns stickyStyles with the appropriate top/bottom offset so the sidebar scrolls naturally through long content without jumping.', NULL, 'function useSticky(options: ISticky): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ac0d2989-e67c-4835-b711-af5cc2b57e75', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'const', 'calendar-month-grid-weeks', 'CALENDAR_MONTH_GRID_WEEKS', 'Calendar', NULL, NULL, NULL, NULL, 'export const CALENDAR_MONTH_GRID_WEEKS = 6', NULL, NULL, '6', 'packages/ds/src/consts/Calendar/calendar.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
