INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('be6e17e7-fd3f-418d-ac09-610229580dd2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'composable', 'use-touch', 'useTouch', NULL, 'Commons', 'mdi-gesture-swipe', '', 'Enables swipe-to-open / swipe-to-close gesture handling for drawer-like components. Listens to touchstart / touchmove / touchend on window, computes drag progress relative to a positioned edge (left, right, top, bottom), and resolves the gesture via velocity-based fling detection using useVelocity.', NULL, 'function useTouch(options: {
