INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('40c3d279-1bf8-4045-aa9a-dd59f57825a8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'interface', 'i-chart-sankey-slots', 'IChartSankeySlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_slots.description', 'Slot signatures exposed by <OrigamChartSankey>. Extends IChartBaseSlots with a node-label slot that replaces the label rendered beside each node, receiving the node name, value, formatted value, resolved colour and column index.', 'export interface IChartSankeySlots extends IChartBaseSlots {
