INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d01d963-3ab6-43e7-8c80-72f9360310ad', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd641fa17-8118-4293-a47d-8ea95427e698', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('862640f4-aacb-42db-9804-00c2e10918f0', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd641fa17-8118-4293-a47d-8ea95427e698', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('03380eff-44a5-450b-8b82-42ec67f3ea54', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd641fa17-8118-4293-a47d-8ea95427e698', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('af1b12d4-2477-47d2-b51b-1e88dd6754ae', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4a58b092-73be-430d-8082-9d4868119139', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c291098b-a03a-4a27-bea6-831caeb2903c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4a58b092-73be-430d-8082-9d4868119139', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae7512a3-8da3-44d6-8616-07be77e2c3af', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4a58b092-73be-430d-8082-9d4868119139', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b1add77-7b86-45d7-8570-3012afc403b9', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd94121ad-2118-4d0c-87d0-2dfe92ac17a1', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('77106540-0b61-4404-af70-974f0dd67a4b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd94121ad-2118-4d0c-87d0-2dfe92ac17a1', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02107ba3-e010-434e-8009-289f739d0487', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd94121ad-2118-4d0c-87d0-2dfe92ac17a1', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81ff1442-bf61-449d-bf7c-42f75e23d672', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'bc78b296-6f11-4260-a0dd-670507e7980e', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dea49727-971c-4e4d-9950-c05c34d2c5e6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '86b7300e-2722-4dea-a2fc-afdc073e1f6b', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('48f68280-9e5b-4203-9081-723222c9098b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'cb905eb0-84f2-40ab-bcad-3eb27880d0c6', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d5b7633-ebe5-4a33-800c-71386e0ce36f', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ff3f4ce-32c6-4ff0-a1d9-95091c0e3e82', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
