INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d50f7bf2-44de-4717-9584-61079a4a6b50', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'be309608-9f86-42f9-ac13-8bbc9e5d4b48', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
