INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2df05d71-453e-459d-81e5-3d33fc6da0a6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('14ff6542-13a5-468c-901f-03e1cd2c3e80', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8106347-e82b-4a06-8b25-a01cb8e6685d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc512ca9-f56a-4a82-b441-52faddbf3df6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b8b61819-4a72-476e-a97f-7ff3c4228fe8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d9dd9756-528c-4890-84d3-484a5e11fcdf', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7efd81ad-5cc0-4e91-a8d7-024ca7e31193', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18cd2daa-cafe-454c-b2f8-ff218ea7ea18', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b61870d-2eaa-4651-8324-a4cb38ea68db', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('149cb121-9165-4322-80ef-721163256d8a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f7d3bf14-54ef-41f6-b9db-82024b658747', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '97ff2211-82e6-4a4c-ace6-ec9141253409', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17a9a005-6b72-4583-b691-180fba6b87a2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '97ff2211-82e6-4a4c-ace6-ec9141253409', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a793bfd0-dc7f-4bad-98fc-d1d93060172a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d202d32-fbaf-49a9-874d-a90a8806dabe', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f83a8654-801a-4556-ace2-17ef354262c6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'eae26b2c-93c3-4c00-b060-56fb9f41edd0', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db95c5e1-5925-4772-841a-2556fa0c5c43', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'eae26b2c-93c3-4c00-b060-56fb9f41edd0', 'isSticky', 'Ref<boolean>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('11c3c91b-a773-4456-8835-be192ba10eeb', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'eae26b2c-93c3-4c00-b060-56fb9f41edd0', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d1798fb-9711-4c93-8286-350599aaf200', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b05f7ec8-1b76-49c8-974e-bc58827a721a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f04a41e5-f683-4639-b46a-fd33fef53a31', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
