INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fbe8964d-fcb3-4a35-9082-35671ae7c5ea', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'de76197d-f011-458a-b5de-06c8887f2873', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
