INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e9f19f5b-a3da-4267-a198-bc401cab6853', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cb38b595-f068-4e95-8b08-75b129326e33', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd58ca975-8189-43a7-9667-81f6456c5ea6', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc0a258b-e7c1-4ede-adbc-5a653cb102c7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd58ca975-8189-43a7-9667-81f6456c5ea6', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da36d018-8dc7-4919-a01d-d9e31f2a8515', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '3898f0df-77ae-4739-a6f3-8e638b238321', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d9053765-8c5a-4cf3-b852-f22d1e7aa782', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '3898f0df-77ae-4739-a6f3-8e638b238321', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('329ef2c1-6b6a-4e72-8fe9-33705f6ca734', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'f9ecdb66-e631-4aeb-9676-c589389dd353', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('70c4e9f1-cf07-4fb4-a411-d05553ace37f', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'f9ecdb66-e631-4aeb-9676-c589389dd353', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
