INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('79b4a073-dd36-4368-9d5b-45e3a2643f2a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb988daf-6ad1-433b-8617-fa7613b6ad27', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bdc3a64c-2c9a-4ecc-9df3-7c39e95692dd', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '271348dd-c55f-435e-b282-9b0df02adb5c', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39b5c9e5-2488-447f-8bb5-dea290b9ef3d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '271348dd-c55f-435e-b282-9b0df02adb5c', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4c2602d2-4ad8-4841-a486-7b0d1681bc08', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '271348dd-c55f-435e-b282-9b0df02adb5c', 'defaultValue', 'MaybeRefOrGetter<Props[Prop] | undefined>', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37de47aa-5c52-4424-b6c3-03f8f01533c9', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '271348dd-c55f-435e-b282-9b0df02adb5c', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
