INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4523db4-a078-4c92-b285-63faf66c8a87', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4f352642-efc2-4108-be26-623f2fbc89a8', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a23f20df-ca4e-4e2f-acbf-01ac558c43d8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9f8d5ccd-f978-4ee9-b61d-29baa32e0273', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('023e4d59-e025-45d5-a3f8-ec9797ca6b86', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9f8d5ccd-f978-4ee9-b61d-29baa32e0273', 'options', 'IUseWaveformOptions', false, '{}', '', 'Optional: `bins` (number of peaks to produce, default 200) and `crossOrigin` ("use-credentials" | undefined) for the fetch credentials policy.', 1, false, NULL, NULL);
