INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ed92bc9-757c-4d45-b2b4-618454346b6d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '7e6669fa-9d7b-4c41-8b89-72d4449c129c', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7297d821-8721-4901-b4df-66f0a52490d3', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '7e6669fa-9d7b-4c41-8b89-72d4449c129c', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e3204733-bc06-4cbe-8436-0bb815ccdc4c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '7e6669fa-9d7b-4c41-8b89-72d4449c129c', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96a94562-1384-4fa7-aa15-f8eb6758c7f0', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '7e6669fa-9d7b-4c41-8b89-72d4449c129c', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
