INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a2767fe5-33eb-4dd7-af82-74ee7371e5fc', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e07ea7ed-7fa9-4047-b305-07cc2d26a958', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f466005-81b8-41a1-8348-be0a796c8f9d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c42c4f7-7835-461b-8b61-f12cc83084b4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c902198c-5c5b-4617-8dd7-63c39f190d63', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7398fff3-d2ba-4731-9b05-4394b6371862', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52e4b414-6084-444b-813d-e47a68608340', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('572bbf4f-00b9-4e13-8a82-9be6c8c0f670', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36d6f78a-7f03-4f09-b9f0-8ac56b79848a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7c07409b-5539-4a10-81ea-12a5ebb413e3', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6d7d6d95-2710-4b32-b515-b72ed6179e34', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '59a98dca-2ccf-40de-986b-7ad3b4fca761', 'scrollerAriaLabel', 'string', NULL, NULL, NULL, false, NULL, NULL, 'Accessible name of the scrollable region. Left out, it is derived from filename, then lang. Set it when several blocks of the same language share a page.', 12, false, NULL, NULL);
