INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c422dd88-5d00-4736-bdec-5f2032dc88c2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c03791f7-bb42-4d76-9285-40b7100772e4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86d756c9-cd1e-4710-a31f-ff49400aeaee', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee478afd-fd2c-4968-a749-b2d4e0e47d22', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5adb538-f668-41d5-99e0-b57ef22e1426', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66a349eb-08ab-443f-9376-a43e0d2477b9', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5974f69-910f-487a-a611-45014f53f412', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee4ecae2-0cad-4800-934a-2e30bc0ac39a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d511d7ac-0ff2-4df7-bffd-4a9016658115', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4324e86-9844-4ff8-a408-fe22aa1f0069', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('00a4b716-84b7-45e3-8a5b-bbc8b0bb28bc', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34f260b9-b4dc-4fb3-b0e2-11ac979ec75d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'showShuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b86ed69e-1aa9-482e-ad5e-69f90fe03492', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'loopMode', 'TAudioLoopMode', '', 'primitive', NULL, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c9ab0963-b88d-4cbb-884f-5da535c6e98d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '10361708-3617-4487-9681-21980a6a0d9d', 'shuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
