INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bcfcde6b-1970-427a-bc53-246bc5931bab', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
