INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ce2f2f0-b3e3-48cf-b2c5-a0c3584ae73a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'max', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.max.description', 'Upper bound of the value range. Required to compute the thumb position. Passing 0 or any value <= min freezes the scrubber at the start.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ddf99b67-7120-488a-bb22-8be115513239', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2d99a53-e0ae-416c-937a-b1abb39b7e47', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'buffered', 'number', '', 'primitive', NULL, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('32b88436-b59a-424e-af29-dbf0e39ecf60', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20c26a18-9f1d-4567-94aa-725476ff5566', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c02e0de-d5da-42de-9080-360d370fc912', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b8c3f52-ed3b-4b81-a894-ff47885038e4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'showHoverTooltip', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_hover_tooltip.description', 'Shows a tooltip above the cursor (horizontal only) reflecting the hovered value. Content can be overridden via the #tooltip slot.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('71c17f41-5d83-47a2-bbca-1709aac24b44', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'formatHoverTooltip', '(value: number) => string', '', 'primitive', NULL, false, 'value => String(value)', 'components.media_scrubber.props.format_hover_tooltip.description', 'Formatter for the default hover tooltip label. Receives the hovered value, returns the string to render.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('668dda52-06ed-4537-8f39-eccf7328253c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:44.457975+00', '368cb110-4952-4bb1-80af-f59269d22e90', 'ariaLabel', 'string', '', 'primitive', NULL, false, '—', 'components.media_scrubber.props.aria_label.description', 'Required accessibility label read by screen readers when the scrubber gains focus. Always pass a translated string here.', 10, false, NULL, NULL);
