INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cb6957b-31ca-4296-9497-dda117dafba1', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '2aa4006b-d2bc-4d40-b754-8c8e3bf4a0e4', 'viewBox', 'ComputedRef<string>', '', 'Pre-formatted SVG viewBox attribute string ("0 0 W H"). The chart always renders at its full logical size; CSS handles visual scaling.', 0, false, NULL, NULL);
