INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('98bfefbc-9254-48d4-943f-499bf87796e8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '2aa4006b-d2bc-4d40-b754-8c8e3bf4a0e4', 'ticks', 'ComputedRef<{ x: Array<IChartTick>; y: Array<IChartTick> }>', '', 'Gridline and axis-label descriptors for both axes. Bar charts swap the axis roles automatically (categorical along Y, value along X).', 2, false, NULL, NULL);
