INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ba43e59a-7eed-47ee-8979-a09d362c7e7d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e200a90d-ff45-4c8a-9fd0-819e12a475cd', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d4d0e96-2a49-4251-aed1-4bf514c5ecff', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8b2eb814-9adc-4549-9860-038a92d51314', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e1e719d-617e-4233-8fc5-73ea4cd9b051', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0fca7d8a-5d8c-414c-99fe-b350a80b6f5c', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('373b6b0a-58b8-4626-a1f6-143549c8deb1', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fa138282-8148-421b-b52c-06b95bb3f76b', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1621b4dc-8d83-4830-b456-82fd6e44ee6a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fa138282-8148-421b-b52c-06b95bb3f76b', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e96db247-bfe1-4fc0-9f85-a0efb476bcb7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5f547f6-f6c9-4259-b2f9-26999014a3a6', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7def6534-5ccc-4bc2-a548-e9623ce9c2f6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5f547f6-f6c9-4259-b2f9-26999014a3a6', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52f5506d-d2ba-4e9f-b351-61c2c25d21c7', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5f547f6-f6c9-4259-b2f9-26999014a3a6', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5467dc80-0701-428e-ab95-b50ef687c3b1', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5f547f6-f6c9-4259-b2f9-26999014a3a6', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61d155bd-a098-4f0c-8b5f-cd92743c9a1e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5f547f6-f6c9-4259-b2f9-26999014a3a6', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c727d708-895a-4dbc-a8e7-0e3fdc518dba', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5a5cd4c-4c01-47ec-9fa8-0ff8afa7a23c', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1e2b7cf6-2dcb-41f6-b715-247c071715e8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5a5cd4c-4c01-47ec-9fa8-0ff8afa7a23c', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0597ae9b-c076-4be5-be6f-7aa327e435ff', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5a5cd4c-4c01-47ec-9fa8-0ff8afa7a23c', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21ad0a14-7d9d-4bec-93c2-a3d60f4be4e5', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e5a5cd4c-4c01-47ec-9fa8-0ff8afa7a23c', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6d8f13fc-752e-42d6-8c88-b0a2e823a56e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '12f3b6c0-4a66-4667-a805-5d7576627748', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f3f63cf-c75d-4525-879b-87d122d08cbe', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '12f3b6c0-4a66-4667-a805-5d7576627748', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30753fc6-b94e-47fb-b92b-872c38d0a447', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '12f3b6c0-4a66-4667-a805-5d7576627748', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59aaaa79-d65b-4d46-97d6-3b3bb078d469', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '12f3b6c0-4a66-4667-a805-5d7576627748', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b94ded83-5b29-4250-a548-4d52d742e4b5', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e8d101c6-a277-4a07-bdba-b4bb7a6b2d47', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a9cfa3e-31a9-48c4-bb35-333d95990440', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e8d101c6-a277-4a07-bdba-b4bb7a6b2d47', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da0476b9-acdb-439a-b024-6a815eeaf495', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e8d101c6-a277-4a07-bdba-b4bb7a6b2d47', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a1117a94-c5bd-4600-aa4d-c3a3221f25a8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e278aac2-42f1-44f7-80ec-e8b74e8eb36c', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0594d306-75a4-40e1-9305-3c50f6c159be', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'e278aac2-42f1-44f7-80ec-e8b74e8eb36c', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('899748bb-de75-4a2f-a56c-24de41be9b8b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '6c5d0ffc-62e9-47bc-803e-4d70f97d67b2', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35fb4685-eecb-499b-a4fc-d4847ddad160', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6754155-cc08-40a6-9d2b-ed1fa5bab8ec', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7583317f-fa8a-4b44-91d0-c8587912a639', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '430fa765-3eb6-4658-9b5b-e887ca2bc655', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0657965-94c5-46b9-8ce6-169d9e8930a5', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43dcf54a-d86a-4b6e-bef1-dafd55db3eca', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('00e0de00-53e5-4516-bcfd-469eef2ea7ca', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c68e86ef-38f8-4bcc-a425-6c9adc73c24b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9ff6a6ff-8d44-41f6-afae-857fe085537b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d044a45-37f3-4b24-89ef-d2ff92fe2839', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8d22ada6-e64c-4e4d-92c1-79c1338859d6', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'fed4f028-1356-4f5e-8838-47893f6b494a', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1cf9e289-de0d-4563-b4e0-37e1044dd647', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49caaa21-e9ad-4db7-b15b-30c77f904ea8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29226ecb-992d-4cad-883f-88f6b16b64e2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6309220-c18a-4385-8277-36915a34b3fc', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('877a1a9d-f34b-49f3-b64a-d253b462e125', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd82e371b-80f0-4369-b7bc-40e7359a6db4', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e596c7e-aa74-4664-8121-44d58af81139', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'eae26b2c-93c3-4c00-b060-56fb9f41edd0', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('793217d6-e748-4f25-90a9-d606c41c700f', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'eae26b2c-93c3-4c00-b060-56fb9f41edd0', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8706f0a9-599c-4900-a435-0c70685eb78b', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2245d6a7-1342-49cb-b667-a50adc753af8', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('346c00f9-24b1-4195-a137-c5caa600a28f', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f47150fa-b870-461b-b21a-6aaf3d7a1fa4', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9ce68f5a-8415-40b7-a645-043a5face975', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('746f69b0-8e0a-42be-8ee9-8de5e061f662', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'de76197d-f011-458a-b5de-06c8887f2873', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47a57b4c-19ad-4445-9f4f-12b0b73176b2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cab5f4eb-c160-45ca-bfc7-d4802e843b63', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1b0fc50-c431-42c5-972a-9b577d4379b1', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('271d9876-a906-45dd-9a63-e1c91cf3ac49', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b4a2297-6f50-4030-a6bc-5e0aa0bbb13c', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '55bd8f17-6ebf-46e0-b08e-4b760ef902f4', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
