INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b721d62c-f250-48c1-92fd-3e7760a6d97d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bcf96e90-f988-40b3-92e6-ad9859d04a9a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18be650a-6d47-440d-a1ef-266959323dd2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
