INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72051089-2e1e-451b-bf36-b252861674cf', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c58365f2-7771-4c10-9dd8-3eb2b403089a', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a201b974-49ec-44c8-9189-ef68c640bd57', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47b78d3f-8e81-4c62-8b6e-84f82de79e46', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'b2bc69cb-35d3-4615-b431-79d8077f4069', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59053ecb-1ede-4092-a664-da3b4671ad5d', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '271348dd-c55f-435e-b282-9b0df02adb5c', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ca0fd8ef-4590-4161-975a-2f7fcffdb065', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4f352642-efc2-4108-be26-623f2fbc89a8', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('33f55fc4-e365-491a-bba8-835e7b8aa7a2', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '4f352642-efc2-4108-be26-623f2fbc89a8', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
