INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0eb8d80c-1a4e-4feb-9ca1-6a055f88b091', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '9f8d5ccd-f978-4ee9-b61d-29baa32e0273', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
