INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45c667c2-48c5-4f2b-b268-ef74f7352e18', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0cdf2939-dcb2-4dcb-bdbf-d89801cb9c74', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d59e5c0-e848-4f79-814e-629ba77c6af3', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0cdf2939-dcb2-4dcb-bdbf-d89801cb9c74', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7856dad-8f0e-4d0d-b8ba-57c35f87fe92', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', '0cdf2939-dcb2-4dcb-bdbf-d89801cb9c74', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d7a7401-4993-45c7-a167-6d2fe642ca40', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd93385b9-cefd-4b6c-a9a1-5e467a84ff2c', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e71b080c-98b0-49bd-97ec-ddbe6764ce9e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd93385b9-cefd-4b6c-a9a1-5e467a84ff2c', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5817df9-d40e-42d2-bee4-c7b0dfafaf4e', '2026-11-17 18:48:18.272249+00', '2026-11-17 18:48:18.272249+00', 'd93385b9-cefd-4b6c-a9a1-5e467a84ff2c', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
